#!/usr/bin/env python3
"""Checks that the C generated by an AOT export contains the baked patches.

Every generated block carries in `_expected[]` the instruction words it was compiled
from (GG1 header: number of words, low PC, high PC). For every word of every patch
(pla-patchlist-v1 list) it finds the block that covers it and compares it with the
patched word. Words no block covers (data inside the code cave, e.g. float constants)
are reported separately: they are not code that runs.

    python recomp/scripts/check-baked-patches.py \
        -p recomp/patches/unlocked-fps/pla-111-unlocked-fps.json \
        --src <root>/exports/pla-v0/pkg/aot_cache/exefs/main/src
"""
from __future__ import annotations

import argparse
import json
import re
import struct
import sys
from pathlib import Path

EXPECTED = re.compile(r"static const uint32_t _expected\[\]=\{(\d+)U,0x([0-9a-f]{8})U,0x([0-9a-f]{8})U,([^}]*)\}")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("-p", "--patches", action="append", required=True)
    ap.add_argument("--src", required=True, help="aot_cache/exefs/main/src")
    args = ap.parse_args()

    want: dict[int, tuple[int, str]] = {}  # word offset -> (word, patch)
    for path in args.patches:
        doc = json.loads(Path(path).read_text(encoding="utf-8"))
        for p in doc["patches"]:
            off = int(p["offset"], 16)
            data = bytes.fromhex(p["patched"])
            for k in range(0, len(data), 4):
                (word,) = struct.unpack_from("<I", data, k)
                want[off + k] = (word, p["offset"])
    lo, hi = min(want), max(want)
    found: dict[int, int] = {}
    files = sorted(Path(args.src).glob("*.c"))
    for f in files:
        with f.open("r", encoding="ascii", errors="replace") as fh:
            for line in fh:
                if "_expected[]" not in line:
                    continue
                m = EXPECTED.search(line)
                if not m:
                    continue
                count = int(m.group(1))
                pc = int(m.group(2), 16) | (int(m.group(3), 16) << 32)
                if pc + 4 * count <= lo or pc > hi:
                    continue
                words = [int(w, 16) for w in m.group(4).replace("U", "").split(",") if w.strip()]
                for i, w in enumerate(words):
                    a = pc + 4 * i
                    if a in want:
                        found[a] = w
    patches = sorted({p for _, p in want.values()}, key=lambda s: int(s, 16))
    ok = bad = 0
    uncovered = []
    for name in patches:
        offs = [a for a, (_, p) in want.items() if p == name]
        miss = [a for a in offs if a not in found]
        wrong = [a for a in offs if a in found and found[a] != want[a][0]]
        if wrong:
            bad += 1
            for a in wrong:
                print(f"MISMATCH main+0x{a:x}: C has {found[a]:08x}, patch {want[a][0]:08x}")
        elif miss and len(miss) == len(offs):
            uncovered.append(name)
        else:
            ok += 1
            if miss:
                print(f"{name}: {len(offs) - len(miss)} words in blocks, {len(miss)} without a block (data)")
    print(f"{len(files)} units; {len(patches)} patches: {ok} present in the C, {bad} mismatched, "
          f"{len(uncovered)} without any block {uncovered}")
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())
